// Asset manifest for DEADLIGHT.
//
// Every mesh in the game is generated by Tripo from the prompts below — there
// are no hand-modelled or downloaded meshes in this prototype. `generate.mjs`
// turns this file into `assets/*.glb`; `optimize.mjs` makes those shippable.
//
// Art direction: a flooded hospital sublevel that was decommissioned mid-shift.
// Everything is enamel, rust and water damage. Nothing is stylised or cute —
// prompts lean on material words ("chipped enamel", "corroded steel") because
// that is what survives the trip through decimation to an 8k-triangle mesh.

// Shared prompt suffix: keeps the whole set on one art direction, and pushes
// the generator away from the display bases it likes to add to props.
const LOOK = 'grimy horror survival game asset, desaturated, water damaged, ' +
  'photoreal PBR, single object, no ground plane, no base, no pedestal';

/**
 * Props. `scale` is the target height in metres — Tripo normalises everything
 * to a unit box, so the game has to be told how big each thing really is.
 * `tag` groups props for the level dresser (see src/level.js).
 */
export const PROPS = [
  {
    key: 'fusebox',
    scale: 0.55,
    tag: 'objective',
    prompt: `a wall-mounted industrial fuse box, corroded steel door hanging ` +
      `open, ceramic fuses and frayed wiring inside, ${LOOK}`,
  },
  {
    key: 'generator',
    scale: 1.15,
    tag: 'objective',
    prompt: `a small diesel backup generator, rusted yellow paint, exhaust ` +
      `pipe, control panel with dials, ${LOOK}`,
  },
  {
    key: 'gurney',
    scale: 0.85,
    tag: 'large',
    prompt: `an abandoned hospital gurney, bent chrome frame, filthy torn ` +
      `mattress, one wheel missing, ${LOOK}`,
  },
  {
    key: 'wheelchair',
    scale: 0.95,
    tag: 'large',
    prompt: `an old hospital wheelchair, rusted spokes, cracked leather seat, ` +
      `${LOOK}`,
  },
  {
    key: 'locker',
    scale: 1.8,
    tag: 'large',
    prompt: `a tall dented steel locker, door ajar, rust streaks and peeling ` +
      `institutional green paint, ${LOOK}`,
  },
  {
    key: 'crt',
    scale: 0.45,
    tag: 'medium',
    prompt: `an old CRT television set, cracked plastic housing, dusty glass ` +
      `screen, broken antenna, ${LOOK}`,
  },
  {
    key: 'barrel',
    scale: 0.9,
    tag: 'medium',
    prompt: `a rusted steel oil drum, dented lid, chemical hazard stains, ` +
      `${LOOK}`,
  },
  {
    key: 'crate',
    scale: 0.6,
    tag: 'medium',
    prompt: `a weathered wooden shipping crate, split slats, water stains and ` +
      `mould, ${LOOK}`,
  },
  {
    key: 'chair',
    scale: 0.9,
    tag: 'medium',
    prompt: `a broken wooden institutional chair, one leg splintered, flaking ` +
      `varnish, ${LOOK}`,
  },
  {
    key: 'doll',
    scale: 0.35,
    tag: 'small',
    prompt: `an antique porcelain doll, cracked face, one eye missing, ` +
      `filthy lace dress, deeply unsettling, ${LOOK}`,
  },
  {
    key: 'lamp',
    scale: 0.32,
    tag: 'ceiling',
    prompt: `a caged industrial ceiling lamp, wire guard over the bulb, ` +
      `rusted enamel shade, hanging from a short chain, ${LOOK}`,
  },
  {
    key: 'sink',
    scale: 0.5,
    tag: 'wall',
    prompt: `a filthy porcelain hospital sink, chipped enamel, rust stains ` +
      `under the taps, exposed pipes, ${LOOK}`,
  },
];

/**
 * The mannequins. These are the game's stalkers: they only move while off
 * screen, so they are static meshes, never animated. Three separate sculpts —
 * repetition is what gives the effect away, and the player looks at these
 * more carefully than at anything else in the level.
 */
export const MANNEQUINS = [
  {
    key: 'mannequin_a',
    scale: 1.85,
    prompt: `a featureless wooden artist mannequin scaled to a full adult ` +
      `human, standing upright, arms hanging at its sides, smooth blank head ` +
      `with no face, cracked varnish, ${LOOK}`,
  },
  {
    key: 'mannequin_b',
    scale: 1.85,
    prompt: `a battered shop display mannequin, full adult human body, ` +
      `standing, blank featureless head, one arm raised, yellowed cracked ` +
      `plaster, hairline fractures, ${LOOK}`,
  },
  {
    key: 'mannequin_c',
    scale: 1.8,
    prompt: `a damaged plaster mannequin, full adult human body, standing ` +
      `slightly hunched, head tilted to one side, blank faceless head, ` +
      `grey mould stains, ${LOOK}`,
  },
];

/**
 * The creature. Generated as a standing A-pose humanoid, auto-rigged as a
 * biped, then retargeted onto the presets below.
 *
 * This prompt is not the obvious one, and the wording is load-bearing. The
 * first attempt asked for what a horror creature actually looks like —
 * "elongated spindly limbs, long clawed fingers" — and Tripo generated it
 * beautifully and then rigged it into spaghetti. The rigger is fitting a human
 * skeleton to a silhouette it has to segment into limbs, and thin separated
 * geometry gives it nothing to attach to. Worse, it fails invisibly: the bind
 * pose is perfect and the skin only tears once a bone moves.
 *
 * So: solid connected limbs of even thickness, mitten hands, human
 * proportions, and the horror carried by the head and the skin rather than by
 * the skeleton. `tools/creature-bakeoff.mjs` is how this was chosen, and it
 * is still there to choose the next one.
 *
 * `animations` maps the game's state names to Tripo rig-v2.5 preset ids.
 * Keep `idle` first: it is the clip the game falls back to if a retarget
 * fails, and a creature standing still is still frightening.
 *
 * Not every v2.5 preset is what its name suggests, and the two that are not
 * are the two an action game most wants. On this rig `preset:run` retargets
 * to a horizontal superman dive, and `preset:slash` to a mid-air backflip —
 * both with the mesh perfectly intact, so they pass every integrity check and
 * fail only when you look at them. Neither is in this list as a result: the
 * creature runs on `walk` at a higher playback rate (src/creature.js resolves
 * missing clips through a fallback chain, and matches rate to ground speed),
 * and lunges with `preset:hurt`, which is a far better strike than the one
 * named after striking.
 */
export const CREATURE = {
  key: 'creature',
  scale: 2.15,
  faceLimit: 30000,
  rigModel: 'v2.5-20260210',
  prompt:
    'a tall gaunt humanoid horror creature standing upright in an A-pose, ' +
    'arms hanging down and slightly away from the body, solid connected ' +
    'limbs of even thickness, smooth featureless head, no separated ' +
    'fingers, closed simple hands, ashen grey skin, full body character ' +
    'model, symmetrical, clean topology, game character, T-pose reference, ' +
    'no base, no pedestal',
  animations: {
    idle: 'preset:idle',
    walk: 'preset:walk',
    lunge: 'preset:hurt',
  },
};

/** Everything that needs a plain text-to-model pass. */
export const ALL_MESHES = [...PROPS, ...MANNEQUINS];
